def find(code: str):
    """The recipe with this code (e.g. ``"6.1"``), or None."""
    for rc in RECIPES:
        if rc["code"] == code:
            return rc
    return None


def unit_cost(recipe, prices: dict) -> tuple[float, list[str]]:
    """Material cost of one unit of work and the item names that have no
    price in ``prices`` (name → baht per the item's unit)."""
    total, missing = 0.0, []
    for it in recipe["items"]:
        price = it.get("price", prices.get(it["name"]))
        if price is None or it.get("qty") is None:
            missing.append(it["name"])
            continue
        total += float(it["qty"]) * float(price)
    return total, missing
